options.css:
.so-podium { background: transparent; box-sizing: border-box; width: 100%; }
.so-podium *, .so-podium *::before, .so-podium *::after { box-sizing: border-box; }
.so-podium__card { display: flex; flex-direction: column; gap: 8px; }
@media (max-width: 619px) { .so-podium__card { gap: 6px; } }
@media (min-width: 620px) and (max-width: 1023px) { .so-podium__card { gap: 8px; } }
@media (min-width: 1024px) { .so-podium__card { gap: 12px; } }

options.apply_js:
(function () {
  var ROOT_CLASS = 'so-podium';
  var utils = optimizely.get('utils');
  var selector = widget.selector;
  function init() {
    if (!selector) { console.warn('[widget] No widget.selector configured'); return; }
    utils.waitForElement(selector).then(function (target) {
      if (!target) { console.warn('[widget] Target not found for selector:', selector); return; }
      if (target.querySelector('.' + ROOT_CLASS)) { return; }
      target.insertAdjacentHTML('beforeend', widget.$html);
    });
  }
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); } else { init(); }
})();
